import {aqueousCases,checkAqueous,practicalTasks,checkPractical} from './aqueous-models.js?v=20261023-physicscomplete01';
import {showAqueous} from './aqueous-scenes.js?v=20261023-physicscomplete01';
const field=(id,label,options)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select>`;
export function mountAqueousWidget(l,p,root,{save,done,feedback}){
 const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const practical=l.widget==='aqueous-practical',cases=practical?practicalTasks:aqueousCases,i=w.task%cases.length,t=cases[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s);
 root.innerHTML=`<p><b>${i+1} / ${cases.length} · ${practical?t.title:t.name}</b></p>`+(practical?`<p>${t.intro}</p>`+t.fields.map(f=>field('aq-'+f.id,f.label,f.options)).join(''):`<p>${t.comparison} Salt ions: ${t.ions.join(' and ')}. Water also contributes H⁺ and OH⁻. Assume inert electrodes.</p><label class="field-label" for="aq-cathode">Cathode product formula</label><input class="lab-input" id="aq-cathode" autocomplete="off" spellcheck="false"><label class="field-label" for="aq-anode">Anode product formula</label><input class="lab-input" id="aq-anode" autocomplete="off" spellcheck="false">`+field('aq-reason','Why this cathode product?',[['metal','Less reactive: metal deposits'],['water','More reactive: hydrogen from water']]))+`<button class="secondary" id="checkAqueous">Check ${practical?'decision':'prediction'}</button><button class="secondary" id="nextAqueous">Next ${practical?'decision':'solution'} →</button><p id="aqueousProgress">${w.passed.length} / ${cases.length} ${practical?'decisions':'predictions'} correct</p>`;
 const keys=practical?t.fields.map(f=>f.id):['cathode','anode','reason'];keys.forEach(k=>{const input=$('#aq-'+k);input.value=a[k]||'';input[input.tagName==='INPUT'?'oninput':'onchange']=e=>{a[k]=e.target.value;save();if(!practical)showAqueous('water',t,false);};});
 // Reveal only a currently correct prediction, even when an earlier attempt passed.
 const currentlyCorrect=()=>practical?checkPractical(t,a).every(r=>r.correct):Object.values(checkAqueous(t,a)).every(Boolean);
 showAqueous(practical?t.id:'water',practical?undefined:t,w.passed.includes(t.id)&&currentlyCorrect());
 $('#checkAqueous').onclick=()=>{const ok=currentlyCorrect();if(!ok){if(practical){feedback(checkPractical(t,a).filter(r=>!r.correct).map(r=>r.why).join(' '),true);}else{const r=checkAqueous(t,a);feedback([!r.cathode?'Cathode: compare the metal with hydrogen; a more reactive metal leaves hydrogen as the product.':'',!r.anode?'Anode: a halide gives a diatomic halogen; without a halide, oxygen forms.':'',!r.reason?'Match your reason to the supplied reactivity comparison.':''].filter(Boolean).join(' '),true);}return;}
 if(!w.passed.includes(t.id))w.passed.push(t.id);save();showAqueous(practical?t.id:'water',practical?undefined:t,true);$('#aqueousProgress').textContent=`${w.passed.length} / ${cases.length} ${practical?'decisions':'predictions'} correct`;feedback(practical?checkPractical(t,a).map(r=>r.why).join(' '):'Both product formulae and your cathode reasoning are correct.');if(w.passed.length===cases.length){p.widgetDone=true;save();done();}};
 $('#nextAqueous').onclick=()=>{w.task=(i+1)%cases.length;save();feedback('');mountAqueousWidget(l,p,root,{save,done,feedback});};
}
